// a kiln temperature monitor (different domain)
// below 800 degrees the kiln needs a boost
export function needsBoost(temp: number): boolean {
  return temp < 800;
}

ui.demo_domain:
// a reading-list page (different domain)
'use client'
import { useEffect, useState } from 'react'
import { isLongTitle } from '@/lib/library/invariants'

export default function LibraryPage() {
  const [books, setBooks] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const load = async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/books')
      if (!res.ok) throw new Error('failed')
      const data = await res.json()
      setBooks(data.books)
      setError('')
    } catch {
      setError('Could not load books')
    } finally {
      setLoading(false)
    }
  }
  useEffect(() => { load() }, [])
  if (loading) return <p>Loading…</p>
  if (error) return <button onClick={load}>Retry</button>
  return (
    <main>
      <h1>Books</h1>
      <ul>
        {books.map((b) => (
          <li key={b.id}>
            {b.title} {isLongTitle(b.title) ? 'long read' : ''}
          </li>
        ))}
      </ul>
    </main>
  )
}
